(() => { const a = window.__CITY_APP, C = window.CITY, P = C.DON_VALLEY, t = a.trafficSystem, cm = a.controllerManager;
  const inPark = (o) => P && P.inBox(o.x, o.z) && Math.abs(P.heightAt(o.x, o.z)) > 0.5;
  const surf = (x, z, y) => { const gg = C.cutAt(x, z), d = C.deckHeightAt(x, z, y + 1, 2.5); return d !== 0 && Math.abs(d - y) < Math.abs(gg - y) ? d : gg; };
  const cars = (t.cars || []).filter((v) => Number.isFinite(v.x) && Number.isFinite(v.y) && inPark(v)).map((v) => ({ x: +v.x.toFixed(1), z: +v.z.toFixed(1), y: +v.y.toFixed(2), d: +Math.abs(v.y - surf(v.x, v.z, v.y)).toFixed(3) })).sort((p, q) => q.d - p.d);
  const feet = (t.peds || []).filter((p) => p.rig && inPark(p)).flatMap((p) => p.rig.feet.map((f) => +Math.min(Math.abs(f.py - C.cutAt(f.px, f.pz)), Math.abs(f.py - C.cutAt(f.px, f.pz) - 0.22), Math.abs(f.py - C.cutAt(f.px, f.pz) - 0.012)).toFixed(3)));
  const e = cm.getActiveEntity().position;
  const ground = (x, z) => +cm.getGroundHeight(x, z, 'person', null).toFixed(2);
  let tris = 0, meshes = 0;
  a.scene.traverse((o) => { if (o.isMesh && /_HighPark$|^HighPark|^PilotPond/.test(o.name) && o.geometry) { meshes++; const gg = o.geometry; tris += (gg.index ? gg.index.count : gg.attributes.position.count) / 3; } });
  const info = a.renderer.info;
  return { pilot: P ? P.regions : null, player: { x: +e.x.toFixed(1), y: +e.y.toFixed(2), z: +e.z.toFixed(1), ground: ground(e.x, e.z) },
    ground: { cafe: ground(-6600, -1993), pondSlope: ground(-6691, -1900), ravine: ground(-6040, -1938), bloorGate: ground(-6285, -2830), queenswayGate: ground(-6314, -1190) },
    cars: cars.length, carWorst: cars.slice(0, 3), feet: feet.length, footWorst: feet.length ? Math.max(...feet) : null,
    drape: C.donValleyStats ? { meshes: C.donValleyStats.stats.reduce((s, q) => s + q.meshes, 0), triangles: C.donValleyStats.stats.reduce((s, q) => s + q.triangles, 0), pieces: C.donValleyStats.stats.reduce((s, q) => s + q.pieces, 0), merged: C.donValleyStats.stats.reduce((s, q) => s + (q.merged || 0), 0), outTriangles: C.donValleyStats.stats.reduce((s, q) => s + (q.outTriangles || 0), 0), outVertices: C.donValleyStats.stats.reduce((s, q) => s + (q.outVertices || 0), 0), plinths: C.donValleyStats.plinths, ms: Math.round(C.donValleyStats.ms) } : null,
    pilotMeshes: meshes, pilotTriangles: tris, renderTriangles: info.render && info.render.triangles, geometries: info.memory && info.memory.geometries,
    heapMB: performance.memory ? Math.round(performance.memory.usedJSHeapSize / 1048576) : null, readyMs: a.startupReadyMs || null,
    terrainNearTris: (() => { const m = a.scene.getObjectByName('TerrainNear'); return m ? m.geometry.index.count / 3 : null; })() };
})()
